public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Create a new graph with the same number of vertices as the target graph
    Graph<V, E> newGraph = new Graph<>(target.getNumVertices());

    // Add all vertices from the target graph to the new graph
    for (V vertex : target.getVertices()) {
        newGraph.addVertex(vertex);
    }

    // Add edges between all pairs of vertices in the new graph
    for (V vertex1 : newGraph.getVertices()) {
