private static Class<?> resolveRawClass(Type type) {
    if (type instanceof Class<?>) {
        return (Class<?>) type;
    } else if (type instanceof ParameterizedType) {
        return resolveRawClass(((ParameterizedType) type).getRawType());
    } else {
        return null;
    }
}

/**
 * Resolves the raw argument for the given type and target type.
 */
private static Class<?> resolveRawArgument(Type type, Class<?> targetType) {
    Class<?> rawClass = resolveRawClass(type);
    if (rawClass == null) {
        return null;
    }

    if (targetType.isAssignableFrom(rawClass)) {
        return rawClass;
    } else {
        return null;
    }
}

