public int addConstantNameAndType(String name, String descriptor) {
    // Check if the constant pool already contains a similar item
    int index = findNameAndType(name, descriptor);
    if (index != NOT_FOUND) {
        return index;
    }

    // Add a new CONSTANT_NameAndType_info to the constant pool
    index = addConstant(CONSTANT_NameAndType, 0);
    writeShort(nameIndex(name));
    writeShort(descriptorIndex(descriptor));

    return index;
}

private int findNameAndType(String name, String descriptor) {
    for (int i = 1; i < maxPoolSize; i++) {
        if (types[i] == CONSTANT_NameAndType &&
                nameIndex(name) == readShort(i) &&
                descriptorIndex(descriptor) == readShort(i + 1)) {
            return i;
        }
    }
    return NOT_FOUND;
}

private int nameIndex(String name) {
    return addConstantUtf8(name);
}

private int descriptorIndex(String descriptor) {
    return addConstantUtf8(descriptor);
}

private int addConstantUtf8(String string) {
    int index = findUtf8(string);
    if (index == NOT_FOUND) {
        index = addConstant(CONSTANT_Utf8, string.length());
        writeString(string);
    }
    return index;
}

private int findUtf8(String string) {
    for (int i = 1; i < maxPoolSize; i++) {
        if (types[i] == CONSTANT_Utf8 && readString(i).equals(string)) {
            return i;
        }
    }
    return NOT_FOUND;
}

private int addConstant(byte type, int length) {
    int index = maxPoolSize;
    types[index] = type;
    offsets[index] = byteCode.length;
    byteCode.write(length);
    return index;
}

private void writeShort(int value) {
