public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            if (line.startsWith("Thread")) {
                String[] parts = line.split("\\s+");
                long threadId = Long.parseLong(parts[1]);
                String threadName = parts[2];
                String groupName = parts[3];
                int depth = Integer.parseInt(parts[4]);
                Map<Integer, ThreadEvent> threadIdToThreadEvent = new HashMap<>();
                StackTrace stackTrace = new StackTrace();
                List<ThreadEvent> threadHistory = new ArrayList<>();
                Map<HprofData.StackTrace, int[]> stackTraces = new HashMap<>();
                while ((line = reader.readLine()) != null) {
                    if (line.startsWith("StackTrace")) {
                        String[] parts = line.split("\\s+");
                        int stackTraceId = Integer.parseInt(parts[1]);
                        int count = Integer.parseInt(parts[2]);
                        int flags = Integer.parseInt(parts[3]);
                        ThreadEventType type = ThreadEventType.valueOf(parts[4]);
                        String parentGroupName = parts[5];
                        String threadName = parts[6];
                        int threadId = Integer.parseInt(parts[7]);
                        String groupName = parts[8];
                        int depth = Integer.parseInt(parts[9]);
                        Map<Integer, ThreadEvent> threadIdToThreadEvent = new HashMap<>();
                        StackTraceElement[] stackFrames = new StackTraceElement[count];
                        for (int i = 0; i < count; i++) {
                            String[] frameParts = reader.readLine().split("\\s+");
                            stackFrames[i] = new StackTraceElement(frameParts[0], frameParts[1], frameParts[2], Integer.parseInt(frameParts[3]));
                        }
                        stackTrace.addStackTrace(stackTraceId, stackFrames, flags, type, parentGroupName, threadName, threadId, groupName, depth);
                    } else if (line.startsWith("ThreadEvent")) {
                        String[] parts = line.split("\\s+");
                        int stackTraceId = Integer.parseInt(parts[1]);
                        int count = Integer.parseInt(parts[2]);
                        int flags = Integer.parseInt(parts[3]);
                        ThreadEventType type = ThreadEventType.valueOf(parts[4]);
                        String parentGroupName = parts[5];
                        String threadName = parts[6];
                        int threadId = Integer.parseInt(parts[7]);
                        String groupName = parts[8];
                        int depth = Integer.parseInt(parts[9]);
                        Map<Integer, ThreadEvent> threadIdToThreadEvent = new HashMap<>();
                        for (int i = 0; i < count; i++) {
                            String[] eventParts = reader.readLine().split("\\s+");
                            long startMillis = Long.parseLong(eventParts[1]);
                            long endMillis = Long.parseLong(eventParts[2]);
                            long duration = Long.parseLong(eventParts[3]);
                            int threadId = Integer.parseInt(eventParts[4]);
                            String threadName = eventParts[5];
                            String groupName = eventParts[6];
                            int depth = Integer.parseInt(eventParts[7]);
                            ThreadEvent threadEvent = new ThreadEvent(startMillis, endMillis, duration, threadId, threadName, groupName, depth);
                            threadIdToThreadEvent.put(threadId, threadEvent);
                        }
                        stackTrace.addThreadEvent(stackTraceId, threadIdToThreadEvent, flags, type, parentGroupName, threadName, threadId, groupName, depth);
                    }
                }
                threadHistory.add(stackTrace);
            }
        }
    }
    return threadSnapshots;
}
